def wiring_bill(n, installed, offers):
    groups = []
    for station in range(n):
        groups.append(station)
    lines = []
    for cable in installed:
        lines.append([cable[0], cable[1], 0])
    for cable in offers:
        lines.append(cable)
    total = 0
    for round in range(n - 1):
        winner = None
        for line in lines:
            if groups[line[0]] != groups[line[1]]:
                if winner is None or line[2] < winner[2]:
                    winner = line
        if winner is None:
            return -1
        old = groups[winner[1]]
        new = groups[winner[0]]
        for station in range(n):
            if groups[station] == old:
                groups[station] = new
        total += winner[2]
    return total

